const ACOLS = ['Invitations sent','Schedule volume for Today (Aimfox)',
               'Schedule volume for Tomorrow (Aimfox)','Schedule volume for Day after tomorrow (Aimfox)'];
const n = v => { const t = String(v ?? '').trim(); if (t === '') return null;
                 const x = Number(t.replace(/[^\d.-]/g, '')); return Number.isFinite(x) ? Math.round(x) : null; };
const rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (String(j.Sequencer ?? '').trim() !== 'Bizon') continue;
  const ws = String(j.Client ?? '').trim();
  const date = String(j.Date ?? '').trim().slice(0, 10);
  if (!ws || !/^\d{4}-\d{2}-\d{2}$/.test(date)) continue;
  if (!ACOLS.some(c => (n(j[c]) ?? 0) !== 0)) continue;   // no Aimfox signal on this row
  rows.push({ ws, date,
    invites_sent:      n(j['Invitations sent']),
    sched_today:       n(j['Schedule volume for Today (Aimfox)']),
    sched_tomorrow:    n(j['Schedule volume for Tomorrow (Aimfox)']),
    sched_day_after:   n(j['Schedule volume for Day after tomorrow (Aimfox)']) });
}
return [{ json: { candidate_rows: rows.length, payload: JSON.stringify(rows) } }];
